export const SLOTS = ['helmet', 'chest', 'legs', 'boots', 'gloves', 'main_hand', 'off_hand'];

export const TIERS = [1, 5, 10, 20, 35, 45, 55, 65, 75, 85, 92];
export const TIER_LEVELS = TIERS;

export function getRarityLabel(rarity) {
  if (!rarity) return 'Unknown';
  return rarity.charAt(0).toUpperCase() + rarity.slice(1);
}

const RARITY_ORDER = ['common', 'uncommon', 'rare', 'epic', 'legendary', 'mythical'];
export function tierToRarity(tier) {
  let best = RARITY_ORDER[0];
  for (const rarity of RARITY_ORDER) {
    if (tier >= LEVEL_REQUIREMENT_BY_RARITY[rarity]) best = rarity;
  }
  return best;
}

export const LEVEL_REQUIREMENT_BY_RARITY = {
  common: 1,
  uncommon: 10,
  rare: 25,
  epic: 45,
  legendary: 65,
  mythical: 90,
};

export const DURABILITY_LOSS_PERCENT_BY_RARITY = {
  common: 5,
  uncommon: 10 / 3,
  rare: 100 / 45,
  epic: 100 / 65,
  legendary: 100 / 90,
  mythical: 100 / 130,
};

export const SLOT_DURABILITY_MULTIPLIER = {
  main_hand: 1.4,
  off_hand: 1.2,
  gloves: 1.15,
  boots: 1.05,
  helmet: 0.95,
  legs: 0.9,
  chest: 0.75,
};

export const REPAIR_COST_PER_PERCENT_BY_RARITY = {
  common: 3,
  uncommon: 9,
  rare: 27,
  epic: 78,
  legendary: 225,
  mythical: 650,
};

const GOD_EQUIPMENT_DURABILITY_MULTIPLIER = 0.25;

export function getDurabilityLossPerFight(item) {

  if (item.source === 'starter') return null;

  if (typeof item.id !== 'string') return null;
  const base = DURABILITY_LOSS_PERCENT_BY_RARITY[tierToRarity(item.tier)] ?? null;
  if (base === null) return null;
  const sourceMultiplier = item.source === 'god_equipment' ? GOD_EQUIPMENT_DURABILITY_MULTIPLIER : 1;
  return base * (SLOT_DURABILITY_MULTIPLIER[item.slot] ?? 1) * sourceMultiplier;
}

export const ADVENTURE_DURABILITY_MULTIPLIER = 1.5;

export function getAdventureDurabilityLossPerTrip(item) {
  const perFight = getDurabilityLossPerFight(item);
  return perFight === null ? null : perFight * ADVENTURE_DURABILITY_MULTIPLIER;
}

export function formatDurabilityPercent(current) {
  if (current <= 0) return 0;
  return Math.max(1, Math.round(current));
}

export function getDurabilityWarningTier(current) {
  if (current <= 0) return 'broken';
  if (current < 25) return 'low';
  return null;
}

export const CHAMPION_FAIL_REDUCTION_BY_TIER = {
  1: 1,
  10: 4,
  20: 6,
  45: 10,
  65: 13,
  92: 16,
};

const GOD_EQUIPMENT_REPAIR_MULTIPLIER_BY_SET = {
  warlords_conquest: 1.1,
  fury_of_the_three: 1.1,
  regalia_of_the_grave_king: 1.1,
  vestments_of_the_last_breath: 1.1,
  sovereignty_of_the_underworld: 1.15,
};

export function getRepairCostPerPercent(item) {

  if (typeof item.id !== 'string') return null;
  const base = HADES_REPAIR_COST_PER_PERCENT_BY_RARITY[tierToRarity(item.tier)] ?? null;
  if (base === null) return null;
  const multiplier = GOD_EQUIPMENT_REPAIR_MULTIPLIER_BY_SET[item.set] ?? 1;
  return multiplier === 1 ? base : Math.ceil(base * multiplier);
}

export function getRepairCurrency() {
  return 'arena';
}

