export const EFFECT_TYPES = {
  CHAMPION_FAIL_REDUCTION: 'champion_fail_reduction',

  CHAMPION_WAGER_BOOST: 'champion_wager_boost',
  ADVENTURE_FASTER_TRIPS: 'adventure_faster_trips',
  ADVENTURE_BETTER_ENCOUNTERS: 'adventure_better_encounters',
  ADVENTURE_SAFER_TRIPS: 'adventure_safer_trips',
  GLADIATOR_XP_BONUS: 'gladiator_xp_bonus',
};

export const EFFECT_LABEL = {
  [EFFECT_TYPES.CHAMPION_FAIL_REDUCTION]: 'Fail Reduction',
  [EFFECT_TYPES.CHAMPION_WAGER_BOOST]: 'Wager Boost',
  [EFFECT_TYPES.ADVENTURE_FASTER_TRIPS]: 'Faster Trips',
  [EFFECT_TYPES.ADVENTURE_BETTER_ENCOUNTERS]: 'Better Encounters',
  [EFFECT_TYPES.ADVENTURE_SAFER_TRIPS]: 'Safer Trips',
  [EFFECT_TYPES.GLADIATOR_XP_BONUS]: 'Gladiator XP Bonus',
};
export const EFFECT_IS_PERCENT = {
  [EFFECT_TYPES.CHAMPION_FAIL_REDUCTION]: true,
  [EFFECT_TYPES.CHAMPION_WAGER_BOOST]: true,
  [EFFECT_TYPES.ADVENTURE_FASTER_TRIPS]: true,
  [EFFECT_TYPES.ADVENTURE_BETTER_ENCOUNTERS]: true,
  [EFFECT_TYPES.ADVENTURE_SAFER_TRIPS]: true,
  [EFFECT_TYPES.GLADIATOR_XP_BONUS]: true,
};

function formatEffectValue(effect) {
  const sign = effect.value >= 0 ? '+' : '';
  const suffix = EFFECT_IS_PERCENT[effect.type] ? '%' : '';
  return `${sign}${effect.value}${suffix} ${EFFECT_LABEL[effect.type] ?? effect.type}`;
}

export function formatItemEffects(item) {
  if (!item.effects || item.effects.length === 0) return '';
  return ` (${item.effects.map(formatEffectValue).join(', ')})`;
}

export function formatItemName(item, { showSet = false, showEffects = true } = {}) {
  const handTag = item.twoHanded ? ' (Two-Handed)' : '';
  const durabilityTag = item.durability
    ? item.durability.broken
      ? ' `[BROKEN]`'
      : ` \`[${formatDurabilityPercent(item.durability.current)}%]\``
    : '';
  const setTag = showSet && item.set && SETS[item.set] ? ` — ${SETS[item.set].name}` : '';
  const ownerTag = item.ownerOnly ? ' 👑' : '';
  return `${item.name}${handTag}${showEffects ? formatItemEffects(item) : ''}${durabilityTag}${setTag}${ownerTag}`;
}

const HAND_SLOT_LABEL = { helmet: 'Helmet', chest: 'Chest', legs: 'Legs', boots: 'Boots', gloves: 'Gloves' };

export function getEquipmentContributions(equipped) {
  const mainHand = equipped.main_hand;
  const offHand = equipped.off_hand;
  const isTwoHanded = Boolean(mainHand?.twoHanded && offHand?.id === mainHand.id);

  const contributions = [];
  for (const slot of ['helmet', 'chest', 'legs', 'boots', 'gloves']) {
    if (equipped[slot]) contributions.push({ label: HAND_SLOT_LABEL[slot], item: equipped[slot] });
  }
  if (isTwoHanded) {
    contributions.push({ label: 'Weapon', item: mainHand });
  } else {
    if (mainHand) contributions.push({ label: 'Main Hand', item: mainHand });
    if (offHand) contributions.push({ label: 'Off Hand', item: offHand });
  }
  return contributions;
}

export const WEAPON_LABELS = new Set(['Weapon', 'Main Hand', 'Off Hand']);

export function getEquipmentEffectTotals(equipped) {
  const totals = {};
  for (const type of Object.values(EFFECT_TYPES)) {
    totals[type] = { total: 0, parts: [] };
  }

  const weaponMaxByType = { [EFFECT_TYPES.GLADIATOR_XP_BONUS]: 0, [EFFECT_TYPES.CHAMPION_WAGER_BOOST]: 0 };
  for (const { label, item } of getEquipmentContributions(equipped)) {
    if (item.durability?.broken) continue;
    for (const effect of item.effects ?? []) {
      if (!totals[effect.type]) totals[effect.type] = { total: 0, parts: [] };
      if (effect.type in weaponMaxByType && WEAPON_LABELS.has(label)) {
        weaponMaxByType[effect.type] = Math.max(weaponMaxByType[effect.type], effect.value);
      } else {
        totals[effect.type].total += effect.value;
      }
      totals[effect.type].parts.push({ label, value: effect.value });
    }
  }
  for (const [type, maxValue] of Object.entries(weaponMaxByType)) {
    totals[type].total += maxValue;
  }
  return totals;
}

export function formatEquipmentEffectSummary(equipped) {
  const totals = getEquipmentEffectTotals(equipped);
  const lines = [];
  for (const type of Object.values(EFFECT_TYPES)) {
    const { total, parts } = totals[type];
    const suffix = EFFECT_IS_PERCENT[type] ? '%' : '';
    const totalSign = total >= 0 ? '+' : '';
    lines.push(`**Total ${EFFECT_LABEL[type]}: ${totalSign}${total}${suffix}**`);
    if (parts.length > 0) {
      let breakdown;
      if (type === EFFECT_TYPES.GLADIATOR_XP_BONUS || type === EFFECT_TYPES.CHAMPION_WAGER_BOOST) {

        const armorParts = parts.filter((p) => !WEAPON_LABELS.has(p.label));
        const weaponParts = parts.filter((p) => WEAPON_LABELS.has(p.label));
        const segments = armorParts.map((p) => `(${p.label} ${p.value >= 0 ? '+' : ''}${p.value}${suffix})`);
        if (weaponParts.length > 0) {
          const weaponJoined = weaponParts.map((p) => `${p.label} ${p.value >= 0 ? '+' : ''}${p.value}${suffix}`).join(', ');
          segments.push(weaponParts.length > 1 ? `(Weapon, best of: ${weaponJoined})` : `(${weaponJoined})`);
        }
        breakdown = segments.join(' + ');
      } else {
        breakdown = parts.map((p) => `(${p.label} ${p.value >= 0 ? '+' : ''}${p.value}${suffix})`).join(' + ');
      }
      lines.push(`${breakdown} = ${totalSign}${total}${suffix}`);
    }
  }
  return lines;
}

