const ITEMS_BY_ID = new Map();
for (const item of ITEMS) {
  ITEMS_BY_ID.set(item.id, item);
  if (typeof item.id === 'number') {
    ITEMS_BY_ID.set(String(item.id), item);
    ITEMS_BY_ID.set(`${item.id}.0`, item);
  }
}

export function getItem(itemId) {
  return ITEMS_BY_ID.get(itemId) ?? null;
}

export function isEquipment(item) {

  return item?.type === 'equipment' || ((item?.type === 'tool' || item?.type === 'outfit') && item?.slot);
}

export function isCollectable(item) {

  return item?.type === 'collectable' || item?.type === 'resource';
}

export function isOwnerOnlyItem(item) {
  return Boolean(item?.ownerOnly);
}

export function hasClaimReward(item) {
  return Boolean(item?.claim);
}

export function isTradeableOverride(item) {
  return Boolean(item?.tradeable);
}

export function getStarterCollectibles() {
  return ITEMS.filter((item) => item.type === 'collectable' && item.source === 'starter' && !item.ownerOnly);
}

export function getStarterKitItems() {
  const starterItemIds = new Set([

    18001,
    18008,
    18015,
    18022,
    18029,

    18043,
    16009,

    'tarnished_coin_pouch',
    'arena_signet',
    'stewards_ledger',
  ]);

  return ITEMS.filter(
    (item) => starterItemIds.has(item.id) && !item.ownerOnly
  );
}

export function getStoreCollectibles() {
  const eligible = ITEMS.filter(
    (item) => item.type === 'collectable' && item.price != null && item.source !== 'arena_store' && !item.ownerOnly
  );
  const regular = eligible.filter((item) => !item.heistCategory).sort(compareItemsForDisplay);
  const heist = eligible.filter((item) => item.heistCategory).sort(compareHeistItemsForDisplay);
  return [...regular, ...heist];
}

export function getChampionDropCollectibles() {
  return ITEMS.filter((item) => item.type === 'collectable' && item.source === 'champion' && !item.ownerOnly);
}

export function getArenaStoreListing() {
  return ITEMS.filter((item) => (item.type === 'equipment' || item.type === 'collectable' || item.type === 'tool') && item.source === 'arena_store' && !item.ownerOnly).sort(
    compareItemsForDisplay
  );
}

export function getAdventureDropCollectibles() {
  return ITEMS.filter((item) => item.type === 'collectable' && item.source === 'adventure' && !item.ownerOnly);
}

export function getItemsBySlot(slot) {
  return ITEMS.filter((item) => item.slot === slot);
}

export function getEquippableItemsForSlot(slot) {
  return getItemsBySlot(slot);
}

export function compareItemsForDisplay(a, b) {
  const tierDiff = (a.tier ?? 0) - (b.tier ?? 0);
  if (tierDiff !== 0) return tierDiff;

  const aSetName = a.set ? SETS[a.set]?.name : null;
  const bSetName = b.set ? SETS[b.set]?.name : null;
  if (aSetName !== bSetName) {
    if (aSetName === null) return 1;
    if (bSetName === null) return -1;
    return aSetName.localeCompare(bSetName);
  }
  return a.name.localeCompare(b.name);
}

export const HEIST_PROTECTION_ORDER = [
  'heist_deposit_box',
  'heist_reinforced_box',
  'heist_fortified_box',
  'heist_decoy_stash',
  'heist_silent_alarm',
  'heist_security_camera',
  'heist_vault',
];
export const HEIST_TOOL_ORDER = [
  'heist_lockpick_set',
  'heist_grappling_hook',
  'heist_crowbar',
  'heist_thermal_drill',
  'heist_master_key',
  'heist_vault_cracker',
  'heist_forged_documents',
  'heist_insider_info',
];

export function compareHeistItemsForDisplay(a, b) {
  if (a.heistCategory !== b.heistCategory) {
    return a.heistCategory === 'protection' ? -1 : 1;
  }
  const order = a.heistCategory === 'protection' ? HEIST_PROTECTION_ORDER : HEIST_TOOL_ORDER;
  return order.indexOf(a.id) - order.indexOf(b.id);
}

function validateCatalog() {
  const seenIds = new Set();
  for (const item of ITEMS) {
    if (seenIds.has(item.id)) {
      throw new Error(`Duplicate item id in catalog: ${item.id}`);
    }
    seenIds.add(item.id);

    if (item.tier != null && !TIERS.includes(item.tier)) {
      throw new Error(`Item ${item.id} has invalid tier: ${item.tier}`);
    }
    if (item.type === 'equipment' && !SLOTS.includes(item.slot)) {
      throw new Error(`Equipment item ${item.id} has invalid slot: ${item.slot}`);
    }
    if (item.type === 'collectable' && item.slot !== null) {
      throw new Error(`Collectable ${item.id} must have slot: null`);
    }
    if (item.type === 'collectable' && item.claim) {
      const { gambling, arena } = item.claim;
      if (!gambling && !arena) {
        throw new Error(`Collectable ${item.id} has a claim block but no gambling or arena reward.`);
      }
      for (const range of [gambling, arena].filter(Boolean)) {
        if (!Number.isInteger(range.min) || !Number.isInteger(range.max) || range.min < 0 || range.max < range.min) {
          throw new Error(`Collectable ${item.id} has an invalid claim reward range.`);
        }
      }
    }
    if (item.type === 'collectable' && item.price != null && (!Number.isInteger(item.price) || item.price <= 0)) {
      throw new Error(`Collectable ${item.id} has an invalid store price.`);
    }
    if (item.set && !SETS[item.set]) {
      throw new Error(`Item ${item.id} references unknown set: ${item.set}`);
    }

    const multiAllowed = item.tier === 92 || item.source === 'arena_store' || MULTI_EFFECT_ALLOWED_IDS.has(item.id);
    if (!multiAllowed && item.effects && item.effects.length > 1) {
      throw new Error(
        `Item ${item.id} (tier ${item.tier}) has ${item.effects.length} effects — only top-tier items, arena_store ` +
          `items (Fail Reduction on armor, or Gladiator XP Bonus + Wager Boost together on weapons, is the ` +
          `design there), and select items in MULTI_EFFECT_ALLOWED_IDS are allowed more than one.`
      );
    }
  }
}

validateCatalog();
